<script setup lang="ts">
import {ref} from 'vue';import {streamChat} from './api/client';import ConnectionsView from './components/ConnectionsView.vue';
const text=ref(''),reply=ref(''),busy=ref(false),connection=ref(false),error=ref('');let conversation=localStorage.getItem('travelbao.chat')||undefined;let active:AbortController|null=null;
function resetChat(){conversation=undefined;reply.value='';localStorage.removeItem('travelbao.chat');}
async function send(){if(busy.value||!text.value.trim())return;busy.value=true;error.value='';reply.value='';active=new AbortController();try{await streamChat(text.value,active.signal,e=>{if(e.type==='conversation'){conversation=e.content;localStorage.setItem('travelbao.chat',e.content);}if(e.type==='delta')reply.value+=e.content;if(e.type==='error')error.value=e.content;},conversation);}catch(e){if(!(e instanceof DOMException&&e.name==='AbortError'))error.value=e instanceof Error?e.message:'请求失败';}finally{busy.value=false;active=null;}}
</script>
<template><main class="connections-view" style="max-width:1000px;margin:30px auto;padding:35px"><button class="secondary-button" @click="connection=!connection">{{connection?'返回对话':'服务连接'}}</button><ConnectionsView v-if="connection"/><section v-else><div class="eyebrow">旅游宝 · 阶段2</div><h1>和旅行助手聊一聊。</h1><p>DeepSeek流式回答 · Advisor保留当前会话近期十条消息。</p><button class="text-link" :disabled="busy" @click="resetChat">开始新会话</button><form @submit.prevent="send"><label for="question">旅行问题</label><textarea id="question" v-model="text" :disabled="busy" maxlength="4000" rows="4" style="display:block;width:100%;margin:18px 0"/><button class="primary-button" :disabled="busy||!text.trim()">发送</button><button v-if="busy" type="button" class="secondary-button" @click="active?.abort()">停止</button></form><p role="alert">{{error}}</p><article style="white-space:pre-wrap;line-height:1.9;margin-top:25px">{{reply}}</article></section></main></template>
